(function (r) { r.ALPUCHE_AI_DATA = {"built":"2026-11-13","office":{"phones":[{"label":"+501 223-1194","tel":"+5012231194"},{"label":"+501 223-1195","tel":"+5012231195"}],"email":"contact@alpuchelaw.com","address":["The Northern Shops, Suite 19","1½ Miles Philip Goldson Highway","Belize City, Belize"],"hours":"Monday to Friday, 8:00 a.m. to 5:00 p.m. Belize time","whatsapp":{"label":"+501 625-3032","href":"https://wa.me/5016253032"},"facebook":"https://www.facebook.com/alpuchelaw"},"practices":[{"key":"real-estate","label":"Real Estate","route":"/practice-areas/real-estate/"},{"key":"corporate-commercial","label":"Corporate & Commercial","route":"/practice-areas/corporate-commercial/"},{"key":"banking-finance-tax-regulatory","label":"Banking, Finance, Tax & Regulatory","route":"/practice-areas/banking-finance-tax-regulatory/"},{"key":"dispute-resolution","label":"Dispute Resolution","route":"/practice-areas/dispute-resolution/"},{"key":"intellectual-property","label":"Intellectual Property","route":"/practice-areas/intellectual-property/"},{"key":"family-law","label":"Family Law","route":"/practice-areas/family-law/"},{"key":"qualified-retired-persons","label":"Qualified Retired Persons Programme","route":"/practice-areas/qualified-retired-persons/"}],"kb":{"FIR-01":{"title":"Who is José M. Alpuche?","answer":"José M. Alpuche is a Belize attorney based in Belize City. He qualified in Belize in 2011 and worked as assistant legal counsel for Caribbean Investment Holdings Limited before establishing his practice.","next":"/about/","examples":["Who is your lawyer?","Who runs the firm?"]},"FIR-02":{"title":"Bar Association role","answer":"José M. Alpuche was elected President of the Bar Association of Belize in March 2026.","next":"/about/","examples":["Is José president of the Bar Association?","Does he have a leadership role?"]},"FIR-03":{"title":"Practice manager","answer":"Janine Ebanks-Alpuche is the firm’s practice manager and provides paralegal support. She is often the first point of contact and previously administered the retirement programme at the Belize Tourism Board. For legal advice, ask to arrange a consultation with the attorney.","next":"/about/","examples":["Who is Janine?","Who will answer my enquiry?","Is Janine an attorney?"]},"FIR-04":{"title":"Office location","answer":"The office is at The Northern Shops, Suite 19, 1½ Miles Philip Goldson Highway, Belize City, Belize.","next":"/contact/","examples":["Where are you located?","What is your address?"]},"FIR-05":{"title":"Phone and email","answer":"Call +501 223-1194 or +501 223-1195, message +501 625-3032 on WhatsApp, or email contact@alpuchelaw.com. For a first enquiry, share only the general topic and how the office can reach you.","next":"/contact/","examples":["Can I speak to someone?","How can I contact the office?"]},"FIR-06":{"title":"Published office hours","answer":"The published hours are Monday to Friday, 8:00 a.m. to 5:00 p.m. Belize time. Call to confirm availability around a public holiday or before travelling.","next":"/contact/","examples":["When are you open?","Are you open on Saturdays?"]},"FIR-07":{"title":"Existing matter","answer":"I can help you reach the office. Please call +501 223-1194 or use the contact channel the firm gave you. Keep case references and personal details out of this chat.","next":"/contact/","examples":["Has my application been filed?","Can I get an update on my case?"]},"FIR-08":{"title":"Scope of practice","answer":"The firm lists real estate, corporate and commercial, banking and finance, tax and regulatory advice, dispute resolution, intellectual property, family law, and advice on Belize’s retirement programme. Tell me the general topic and I can point you to the relevant page.","next":"/practice-areas/","examples":["What kind of law do you practise?","Do you help businesses and individuals?"]},"FIR-09":{"title":"Unlisted service","answer":"That service is not listed in the firm’s current practice areas. Please call the office to confirm whether the firm can help or suggest an appropriate next step.","next":"/contact/","examples":["Do you do wills, criminal defence, employment law or general immigration?"]},"FIR-10":{"title":"WhatsApp, language and availability","answer":"You can message the office on WhatsApp at +501 625-3032, or call or email. Ask the office about language arrangements or availability. I can share the contact page.","next":"/contact/","examples":["Can I WhatsApp you?","Do you offer appointments in Spanish?","Do you have a slot today?"]},"CON-01":{"title":"Arrange a consultation","answer":"Call the office or email a brief enquiry with the general type of matter. The office can explain availability and how to arrange a consultation.","next":"/contact/","examples":["How do I book?","I need to talk to José.","Can you get me an appointment?"]},"CON-02":{"title":"Enquiry from overseas","answer":"You can call or email the office from abroad. Share your time zone and general topic and ask the office what consultation arrangements are available.","next":"/working-with-us/","examples":["Can I contact you from Canada?","Do I have to be in Belize to make an enquiry?"]},"CON-03":{"title":"Consultation costs and payments","answer":"Ask the office about current consultation or legal fees. The amount may depend on the work and any third-party costs. The office can confirm approved payment arrangements directly.","next":"/contact/","examples":["What do you charge?","Is the first call free?","Can you send bank details?"]},"CON-04":{"title":"Documents, uploads and sensitive information","answer":"Please keep documents and personal details out of this chat. Ask the office how to share the material if a review is arranged. You can give the office the general subject and mention any important date.","next":"/contact/","examples":["Can I upload my passport?","Read my contract.","Here are my children’s names."]},"CON-05":{"title":"Representation and confidentiality","answer":"An enquiry or chat does not establish representation. The firm must confirm acceptance and engagement terms. Please do not send confidential information or serve documents here. Contact the office directly for instructions.","next":"/website-notice/","examples":["Are you my lawyer now?","Is this chat privileged?","Can you accept service?"]},"CON-06":{"title":"Urgent deadlines","answer":"Call the office promptly at +501 223-1194 or +501 223-1195 and mention the date and type of document. I cannot determine a legal deadline. If you cannot reach the office and time is short, seek prompt help from another Belize attorney.","next":"/contact/","examples":["My hearing is tomorrow.","I got court papers.","Is my deadline Friday?"]},"CON-07":{"title":"Immediate danger","answer":"If you are in immediate danger in Belize, call emergency services on 911 now if you can safely do so. If you are outside Belize, contact your local emergency services.","next":"https://www.belizepolice.bz/about-911/","examples":["Someone is threatening me now.","I am in immediate danger."]},"CON-08":{"title":"Specific legal advice or outcome","answer":"A Belize attorney would need to review the facts and any documents to advise you. I can direct you to the relevant service or give you the office contact details.","next":"/contact/","examples":["Do I have a good case?","Tell me what to sign.","Will a judge agree?"]},"RE-01":{"title":"Buying or selling","answer":"The firm assists with Belize property transactions, including title searches and transfer documents. Tell the office whether you are buying or selling, and mention any proposed deposit or closing date.","next":"/practice-areas/real-estate/","examples":["Do you handle conveyancing?","I want to buy or sell land in Belize."]},"RE-02":{"title":"Title search","answer":"The firm assists with title searches. A search can help identify the recorded owner and recorded interests. Ask the office how to provide the property reference or title documents.","next":"/practice-areas/real-estate/","examples":["Can you check who owns a parcel?","Can you see whether a mortgage is registered?"]},"RE-03":{"title":"Deposit and contract","answer":"An attorney can review the proposed deposit, refund terms and conditions before you commit. Contact the office with the general details and any proposed signing or payment date.","next":"/insights/buying-property-in-belize/","examples":["Should I pay a deposit now?","Is my purchase agreement safe?"]},"RE-04":{"title":"Overseas buyer and payment","answer":"The type of property, the parties and the transaction matter. The Central Bank publishes prior-notice requirements for transfers between residents and non-residents. Ask the firm to review whether those requirements apply to your purchase.","next":"/practice-areas/real-estate/","examples":["Can a non-resident buy this property?","Does Central Bank notice apply?"]},"RE-05":{"title":"Cost and timing","answer":"The office can discuss likely categories of cost and timing after reviewing the transaction. Tell the office the type of property and the planned closing date. I cannot quote duties, fees or a completion date.","next":"/contact/?area=real-estate","examples":["How much is stamp duty?","How long will registration take?","What will my closing cost?"]},"RE-06":{"title":"Boundary, access or development","answer":"Access, boundaries and planned use can need separate checks. Tell the office how you plan to use the property and ask which legal or other professional reviews may be needed.","next":"/insights/buying-property-in-belize/","examples":["Does title prove access?","Can I build on this lot?"]},"CO-01":{"title":"Formation","answer":"The firm can discuss Belize company and partnership structures and assist with formation within its scope. The Belize Companies and Corporate Affairs Registry operates the Online Business Registry System.","next":"/practice-areas/corporate-commercial/","examples":["Can you form a Belize company or LLP?","I want to register a business."]},"CO-02":{"title":"Business name and incorporation","answer":"Business-name registration and company incorporation are different steps. The right structure depends on the owners and business activity. The firm can discuss those questions with you.","next":"/insights/starting-a-business-in-belize/","examples":["Is a registered business name a company?","Do I need both?"]},"CO-03":{"title":"Foreign participant and registered agent","answer":"BCCAR guidance says a business entity with a foreign participant must use a licensed registered agent. The office can discuss Belize legal advice and whether a referral to a licensed provider is needed.","next":"/practice-areas/corporate-commercial/","examples":["Can I form a company if I live abroad?","Are you my registered agent?"]},"CO-04":{"title":"Shareholder agreement or joint venture","answer":"The firm advises on shareholder arrangements, partnerships and joint ventures. Useful topics to raise include ownership, contributions, decisions, transfers and what happens if a participant leaves.","next":"/practice-areas/corporate-commercial/","examples":["Do you draft shareholder agreements?","I am going into business with someone."]},"CO-05":{"title":"Commercial contract","answer":"The firm advises on Belize commercial arrangements and transactions. Call or email with the type of agreement, the countries involved and any signing date. Ask how to share the draft.","next":"/contact/?area=corporate-commercial","examples":["Can you review a supplier contract?","Can you write a contract for my business?"]},"BFT-01":{"title":"Loans and facility agreements","answer":"The firm reviews and drafts banking and financing documents, including facility agreements. Tell the office what stage the financing is at and when the documents are due.","next":"/practice-areas/banking-finance-tax-regulatory/","examples":["Can you review my loan agreement?","I have a term sheet."]},"BFT-02":{"title":"Guarantee, mortgage or charge","answer":"The firm works with guarantees, mortgages and charges. An attorney needs to review the document and your circumstances before advising on what you would be agreeing to.","next":"/practice-areas/banking-finance-tax-regulatory/","examples":["Should I sign a personal guarantee?","Can the firm prepare mortgage documents?"]},"BFT-03":{"title":"Tax assessment or notice","answer":"The firm advises and represents clients on Belize tax matters. If the notice includes a date, call the office promptly. Keep tax IDs, figures and records out of the chat.","next":"/contact/?area=banking-finance-tax-regulatory","examples":["I received a notice from Belize Tax Service.","What tax do I owe?"]},"BFT-04":{"title":"Regulatory licensing","answer":"Whether a licence is needed depends on the activity and applicable rules. The firm can discuss the Belize regulatory questions. The Financial Services Commission publishes information on providers in its remit.","next":"/practice-areas/banking-finance-tax-regulatory/","examples":["Do I need an FSC licence?","Can I operate this financial service?"]},"BFT-05":{"title":"Cross-border finance","answer":"The Central Bank publishes Belize exchange-control guidance. Share the countries involved and the general type of financing with the office so an attorney can review what applies.","next":"/practice-areas/banking-finance-tax-regulatory/","examples":["Can a foreign lender fund my business?","Will exchange controls apply?"]},"DR-01":{"title":"Litigation and civil disputes","answer":"The firm advises and represents clients in Belize court proceedings. Tell the office the general nature of the dispute and any date shown on papers you have received.","next":"/practice-areas/dispute-resolution/","examples":["I have a contract dispute.","Can you represent me in court in Belize?"]},"DR-02":{"title":"Arbitration","answer":"The firm advises and represents clients in arbitration. An attorney can review the clause, the nature of the dispute and which procedural questions need attention.","next":"/practice-areas/dispute-resolution/","examples":["Our agreement says arbitration.","Does the firm handle arbitration?"]},"DR-03":{"title":"Mediation","answer":"Mediation uses a neutral facilitator to help parties explore an agreement. The firm can advise or represent a party in mediation. Arbitration generally involves an arbitrator deciding issues under the applicable rules.","next":"/practice-areas/dispute-resolution/","examples":["Can you help with mediation?","Is mediation the same as arbitration?"]},"DR-04":{"title":"Demand letter, hearing or time limit","answer":"Call the office promptly and say when you received the papers and which date is shown. Ask how to share them. An attorney needs to review the papers before advising on time limits or how to respond.","next":"/contact/?area=dispute-resolution","examples":["I received a demand letter.","How many days do I have?"]},"IP-01":{"title":"Trademark","answer":"The firm assists with trademark registration in Belize. Relevant starting points include the proposed name or logo, who will own it, and the goods or services involved.","next":"/practice-areas/intellectual-property/","examples":["Can you register my logo?","How do I protect my brand in Belize?"]},"IP-02":{"title":"Patent","answer":"The firm assists with Belize patent registration. If you expect to disclose the invention soon, call the office promptly and ask how to discuss it privately. Please keep technical details out of the chat.","next":"/practice-areas/intellectual-property/","examples":["Can you help patent an invention?","I am about to show investors my prototype."]},"IP-03":{"title":"Copyright","answer":"The firm advises on copyright protection. Ownership can depend on the work and any agreement, so ask the attorney to review the specific circumstances. BELIPO also publishes general copyright information.","next":"/practice-areas/intellectual-property/","examples":["Do you help with copyright?","Who owns work commissioned from a designer?"]},"IP-04":{"title":"Foreign registrations and conflicting brands","answer":"Protection depends on the rights and territories covered. The firm can review the Belize question and whether registration or dispute advice is appropriate.","next":"/practice-areas/intellectual-property/","examples":["Does my US trademark cover Belize?","A competitor copied my name."]},"FA-01":{"title":"Divorce","answer":"The firm advises and represents clients in Belize divorce matters. You can contact the office to discuss arranging a consultation. Mention any existing proceedings or important date in general terms.","next":"/practice-areas/family-law/","examples":["Can you help with a divorce in Belize?","Can I talk before deciding whether to file?"]},"FA-02":{"title":"Adoption","answer":"The firm lists adoption as part of its family law practice. If another country is involved, tell the office which countries are involved and ask to discuss the legal process with the attorney.","next":"/practice-areas/family-law/","examples":["Does the firm handle adoption?","Can I adopt from abroad?"]},"FA-03":{"title":"Children, maintenance and existing orders","answer":"An attorney needs to review the circumstances and any existing orders. You can contact the office about a family matter and mention any scheduled hearing. Keep names of children and details of the case out of this chat.","next":"/contact/?area=family-law","examples":["Can I move with my child?","Can I change a court order?","How do I get maintenance?"]},"FA-04":{"title":"Safe contact","answer":"Use a contact method that is safe for you and tell the office how it can safely reach you. If you are in immediate danger in Belize, call 911 if you can safely do so.","next":"/contact/","examples":["Someone can see my email.","I need to speak privately."]},"QRP-01":{"title":"What the programme is","answer":"The QRP is Belize’s retirement programme administered by the Belize Tourism Board. The firm advises prospective applicants on the programme and related Belize property questions.","next":"/practice-areas/qualified-retired-persons/","examples":["What is QRP?","Can you help me retire in Belize?"]},"QRP-02":{"title":"Eligibility, income and fees","answer":"The Belize Tourism Board publishes current requirements and fees. The firm can discuss how the criteria relate to your plans. I cannot confirm eligibility or quote a current programme fee.","next":"https://www.belizetourismboard.org/programs-events/retirement-program/","examples":["Am I old enough?","What is the exact income minimum?","How much does it cost?"]},"QRP-03":{"title":"Family and application records","answer":"The programme has published requirements for applicants and eligible dependants. Ask the office how those requirements may apply and how to provide any records securely.","next":"/practice-areas/qualified-retired-persons/","examples":["Can I include my spouse or child?","What documents do I need?"]},"QRP-04":{"title":"Work, business, tax or permanent residency","answer":"The programme has its own status and conditions. Ask the firm about your proposed activity and whether separate permissions or specialist advice may be needed.","next":"/practice-areas/qualified-retired-persons/","examples":["Can I work or run a business under QRP?","Do I become a permanent resident or stop paying taxes?"]},"QRP-05":{"title":"Goods, vehicles and timing","answer":"The Belize Tourism Board publishes conditions for programme benefits. Speak with the office and check the current BTB guidance before committing to a shipment or purchase.","next":"/insights/planning-retirement-in-belize/","examples":["Can I import a car duty-free?","Should I ship my furniture before approval?"]},"QRP-06":{"title":"Buying property while planning retirement","answer":"The programme and a property purchase involve separate decisions. The firm can discuss the QRP and assist with Belize title searches and transfer documentation.","next":"/practice-areas/real-estate/","examples":["Should I buy a house before applying?","Does QRP automatically handle my property transfer?"]}},"docs":[{"kind":"intro","id":"/about/#:the-people-behind-the-practice","route":"/about/","anchor":"","page":"Our Team","title":"The people behind the practice","text":"Our office is in Belize City. We work with individuals, families and businesses on matters that range from a property transfer or company decision to a dispute or a planned move to Belize. José leads the legal work. Janine manages the practice and helps clients understand how to take the first step."},{"kind":"section","id":"/about/#jose-m-alpuche:jose-m-alpuche","route":"/about/","anchor":"jose-m-alpuche","page":"Our Team","title":"José M. Alpuche","text":"José qualified as an attorney in Belize in 2011. He earned his law degree from the University of London in 2005 and completed the Bar Vocational Course at the University of the West of England in Bristol in 2009. He served as assistant legal counsel at Caribbean Investment Holdings Limited through December 2018 before establishing his own practice. His experience as in-house counsel informs how he approaches a commercial instruction. A financing agreement, a shareholder decision or a dispute can affect how a client runs its business long after the document is signed. Understanding those consequences is part of understanding the instruction. José was elected President of the Bar Association of Belize at its March 2026 annual general meeting."},{"kind":"section","id":"/about/#janine-ebanks-alpuche:janine-ebanks-alpuche","route":"/about/","anchor":"janine-ebanks-alpuche","page":"Our Team","title":"Janine Ebanks-Alpuche","text":"Janine oversees practice administration and provides paralegal support. She is often the first person you will speak with when you contact the office. She can help you find the appropriate point of contact and explain how to arrange an initial conversation. Before joining the practice, Janine worked in the Belize Tourism Board’s Product Development Department. Her responsibilities included administering the Qualified Retired Persons Programme and organising national events, including Taste of Belize and the Belize Tourism Awards. That experience gives the practice an administrative perspective on what it takes to prepare for a move to Belize."},{"kind":"section","id":"/about/#what-we-want-clients-to-understand-from-the-outset:what-we-want-clients-to-understand-from-the-outset","route":"/about/","anchor":"what-we-want-clients-to-understand-from-the-outset","page":"Our Team","title":"What we want clients to understand from the outset","text":"What needs attention now. A pending closing, filing, agreement or hearing may affect the order in which the work needs to happen.. What the legal work involves. The first conversation helps identify which facts and documents are relevant and which questions need further review.. What the next step looks like. If the firm can assist, the office can discuss scope and fee arrangements before work begins."},{"kind":"intro","id":"/practice-areas/real-estate/#:real-estate-law-in-belize","route":"/practice-areas/real-estate/","anchor":"","page":"Real Estate","title":"Real estate law in Belize","text":"A purchase price and a proposed closing date tell only part of the story. The buyer and seller also need to know what property is being transferred, whether the seller can transfer it, what conditions have to be met and how ownership will be recorded. Legal review gives those questions a place in the transaction before money changes hands. The firm assists buyers and sellers with title searches and the preparation and filing of the legal documents needed for a transfer in Belize. We can discuss what needs checking first and how any issues found during review affect the next step."},{"kind":"service","id":"/practice-areas/real-estate/#how-we-can-help:title-and-ownership-checks-real-estate","route":"/practice-areas/real-estate/","anchor":"how-we-can-help","page":"Real Estate","title":"Title and ownership checks (Real Estate)","text":"Start with the property’s identifiers and the seller’s title documents. A search can help establish who is recorded as owner and identify recorded interests, such as a mortgage or another charge. If the proposed seller is a company, or someone is signing for another person, authority to sign deserves its own review."},{"kind":"service","id":"/practice-areas/real-estate/#how-we-can-help:purchase-and-sale-terms-real-estate","route":"/practice-areas/real-estate/","anchor":"how-we-can-help","page":"Real Estate","title":"Purchase and sale terms (Real Estate)","text":"Review how the agreement handles the deposit, completion date, outstanding conditions and the documents the parties must provide. Where the buyer expects financing or needs an issue resolved before committing, discuss how to address it in the agreement."},{"kind":"service","id":"/practice-areas/real-estate/#how-we-can-help:transfer-documentation-and-registration-real-estate","route":"/practice-areas/real-estate/","anchor":"how-we-can-help","page":"Real Estate","title":"Transfer documentation and registration (Real Estate)","text":"Prepare and file the transfer documents appropriate to the property and its title. The Land Registry and Land Titles Unit and the Ministry’s land transfer guidance are useful starting points for understanding the administrative steps."},{"kind":"service","id":"/practice-areas/real-estate/#how-we-can-help:closings-with-an-overseas-party-real-estate","route":"/practice-areas/real-estate/","anchor":"how-we-can-help","page":"Real Estate","title":"Closings with an overseas party (Real Estate)","text":"Raise overseas signing, the proposed movement of funds and the parties’ residence status early. The Central Bank of Belize publishes prior-notice requirements for transfers between a resident and a non-resident. Counsel can review how those requirements apply to your transaction."},{"kind":"section","id":"/practice-areas/real-estate/#what-deserves-a-closer-look:what-deserves-a-closer-look","route":"/practice-areas/real-estate/","anchor":"what-deserves-a-closer-look","page":"Real Estate","title":"What deserves a closer look","text":"A registered title search can answer important ownership questions. It does not answer every question about the property. If access depends on a road across another parcel, the advertised boundaries differ from the survey, or your plans depend on a particular use, identify that issue early. Surveying, valuation, planning or physical inspection may need a separate professional. It can also help to discuss closing costs before you settle on a budget. Duties or charges, registry costs, legal fees and other professional costs can vary with the transaction. Ask for a breakdown once the office understands the property, the parties and the proposed terms."},{"kind":"section","id":"/practice-areas/real-estate/#three-situations-worth-raising-early:three-situations-worth-raising-early","route":"/practice-areas/real-estate/","anchor":"three-situations-worth-raising-early","page":"Real Estate","title":"Three situations worth raising early","text":"Buying a condominium or unit in a development. Ask what the documents say about the unit, common areas, parking and use restrictions. If you intend to rent the unit or use it for a business, raise that before relying on a brochure or verbal assurance.. Buying land outside a familiar development. Ask which title and registry process applies to the parcel. A parcel reference, a survey plan and a title instrument serve different purposes. An attorney can identify what belongs in the legal review and when separate survey advice is needed.. Buying where a lender is involved. Discuss how the lender’s conditions fit with the deadlines in the purchase agreement. A financing offer can still be subject to valuation, title review or documents the seller must provide."},{"kind":"faq","id":"/practice-areas/real-estate/#when-should-i-ask-an-attorney-to-review-a-purchase:when-should-i-ask-an-attorney-to-review-a-purchase","route":"/practice-areas/real-estate/","anchor":"when-should-i-ask-an-attorney-to-review-a-purchase","page":"Real Estate","title":"When should I ask an attorney to review a purchase?","text":"Ideally, before signing a binding agreement or paying a substantial deposit. If you have signed already, tell the office whether there is a deposit date, financing condition or proposed closing."},{"kind":"faq","id":"/practice-areas/real-estate/#i-live-abroad-can-i-start-the-conversation-before-travelling:i-live-abroad-can-i-start-the-conversation-before-travelling","route":"/practice-areas/real-estate/","anchor":"i-live-abroad-can-i-start-the-conversation-before-travelling","page":"Real Estate","title":"I live abroad. Can I start the conversation before travelling?","text":"Yes. Contact the office with a general description of the property and your plans. Ask which steps can be discussed before you travel and which signatures, identification or certifications may be needed later."},{"kind":"faq","id":"/practice-areas/real-estate/#what-should-i-have-available-for-the-first-discussion:what-should-i-have-available-for-the-first-discussion","route":"/practice-areas/real-estate/","anchor":"what-should-i-have-available-for-the-first-discussion","page":"Real Estate","title":"What should I have available for the first discussion?","text":"The parcel or title reference, seller or agent’s description, proposed purchase terms, any agreement already signed, and relevant dates are useful starting points. Wait for the office to confirm how to share documents."},{"kind":"faq","id":"/practice-areas/real-estate/#can-i-use-a-company-to-buy:can-i-use-a-company-to-buy","route":"/practice-areas/real-estate/","anchor":"can-i-use-a-company-to-buy","page":"Real Estate","title":"Can I use a company to buy?","text":"That depends on the property, the proposed buyer and the purpose of the transaction. The legal review may need to consider the company’s authority, its structure and any financing or exchange-control questions."},{"kind":"intro","id":"/practice-areas/corporate-commercial/#:corporate-and-commercial-law-in-belize","route":"/practice-areas/corporate-commercial/","anchor":"","page":"Corporate & Commercial","title":"Corporate and commercial law in Belize","text":"A sound business arrangement answers questions that can feel premature at the start. Who can commit the company? What decisions require consent? What happens if one owner wants out, or a project needs more money? Putting those answers in writing helps the parties see what they have agreed while they still have room to negotiate. We advise on business structuring and commercial transactions involving Belize. Our work includes company and partnership formation, shareholder arrangements, joint ventures and agreements for local and cross-border transactions."},{"kind":"service","id":"/practice-areas/corporate-commercial/#how-we-can-help:setting-up-a-business-corporate-and-commercial","route":"/practice-areas/corporate-commercial/","anchor":"how-we-can-help","page":"Corporate & Commercial","title":"Setting up a business (Corporate & Commercial)","text":"Discuss the proposed owners, management, activities and funding before choosing how to organise the venture. The practice can assist with domestic company formation, including companies limited by shares or by guarantee, and with limited liability partnerships where appropriate."},{"kind":"service","id":"/practice-areas/corporate-commercial/#how-we-can-help:shareholder-and-partnership-arrangements-corporate-and-commercial","route":"/practice-areas/corporate-commercial/","anchor":"how-we-can-help","page":"Corporate & Commercial","title":"Shareholder and partnership arrangements (Corporate & Commercial)","text":"Clarify voting and decision rights, contributions, restrictions on transfers and what happens on exit. Where a business depends heavily on one individual or a small number of owners, agree early on how the venture will handle an unexpected departure or a disagreement."},{"kind":"service","id":"/practice-areas/corporate-commercial/#how-we-can-help:joint-ventures-and-transactions-corporate-and-commercial","route":"/practice-areas/corporate-commercial/","anchor":"how-we-can-help","page":"Corporate & Commercial","title":"Joint ventures and transactions (Corporate & Commercial)","text":"Agree what each party is bringing, who controls spending and delivery, and how revenues, assets and risks are allocated. For an agreement already in draft, we can identify the provisions that call for commercial instructions before the parties sign."},{"kind":"service","id":"/practice-areas/corporate-commercial/#how-we-can-help:commercial-agreements-corporate-and-commercial","route":"/practice-areas/corporate-commercial/","anchor":"how-we-can-help","page":"Corporate & Commercial","title":"Commercial agreements (Corporate & Commercial)","text":"Review the actual deal behind the language. A useful agreement deals with delivery, payment, variations, ownership of work product and termination in terms the people running the business can apply."},{"kind":"section","id":"/practice-areas/corporate-commercial/#doing-business-with-a-belize-connection:doing-business-with-a-belize-connection","route":"/practice-areas/corporate-commercial/","anchor":"doing-business-with-a-belize-connection","page":"Corporate & Commercial","title":"Doing business with a Belize connection","text":"The Belize Companies and Corporate Affairs Registry operates the Online Business Registry System for business names, companies, limited liability partnerships and various filings. The Registry’s published guidance states that business entities with a foreign participant must use a licensed registered agent. Where regulated agent services or a specialist provider are needed, the practice can discuss the appropriate referral. Formation is one part of establishing an operating business. The activity, customers and location can raise separate issues about permissions, tax registration, finance, property or banking. A workable plan identifies which questions belong with the attorney and which require an accountant, licensed provider or regulator."},{"kind":"section","id":"/practice-areas/corporate-commercial/#common-instructions-and-decisions:common-instructions-and-decisions","route":"/practice-areas/corporate-commercial/","anchor":"common-instructions-and-decisions","page":"Corporate & Commercial","title":"Common instructions and decisions","text":"Two owners are starting a new company. They may need to agree who signs, how profits or new funding will be handled, and what happens if votes are evenly split. Company registration and the owners’ agreement solve different problems.. An overseas business wants a local partner. The parties should agree whether they are forming a new entity or contracting through existing businesses. Clarify who signs local contracts, who owns customer relationships and what happens to shared assets if the arrangement ends.. An established company is taking on an investor. Review any existing restrictions on issuing or transferring shares. Discuss what information and approval rights the investor will receive and how the investment affects existing owners."},{"kind":"faq","id":"/practice-areas/corporate-commercial/#does-a-registered-business-name-create-a-company:does-a-registered-business-name-create-a-company","route":"/practice-areas/corporate-commercial/","anchor":"does-a-registered-business-name-create-a-company","page":"Corporate & Commercial","title":"Does a registered business name create a company?","text":"Business-name registration and company incorporation are different steps. Tell us who will own the venture, what it will do and who needs to sign its agreements, so we can discuss which structure merits consideration."},{"kind":"faq","id":"/practice-areas/corporate-commercial/#when-is-a-shareholder-agreement-worth-discussing:when-is-a-shareholder-agreement-worth-discussing","route":"/practice-areas/corporate-commercial/","anchor":"when-is-a-shareholder-agreement-worth-discussing","page":"Corporate & Commercial","title":"When is a shareholder agreement worth discussing?","text":"When more than one person will own the business, discuss how the owners want to make decisions, transfer interests and handle disagreements. It is often easier to agree on these points before a dispute or funding event makes them urgent."},{"kind":"faq","id":"/practice-areas/corporate-commercial/#can-the-firm-assist-a-business-based-abroad:can-the-firm-assist-a-business-based-abroad","route":"/practice-areas/corporate-commercial/","anchor":"can-the-firm-assist-a-business-based-abroad","page":"Corporate & Commercial","title":"Can the firm assist a business based abroad?","text":"The firm advises on Belize aspects of cross-border arrangements. Tell us where the parties are based, what activity will take place in Belize and whether you already have advisers in another jurisdiction."},{"kind":"faq","id":"/practice-areas/corporate-commercial/#what-should-i-bring-to-the-first-discussion:what-should-i-bring-to-the-first-discussion","route":"/practice-areas/corporate-commercial/","anchor":"what-should-i-bring-to-the-first-discussion","page":"Corporate & Commercial","title":"What should I bring to the first discussion?","text":"A short description of the business, a list of the proposed ownership and decision roles for your own reference, and any draft terms or signed documents. Start with the general outline and ask the office for document-sharing instructions."},{"kind":"intro","id":"/practice-areas/banking-finance-tax-regulatory/#:banking-finance-tax-and-regulatory-law-in-belize","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"","page":"Banking, Finance, Tax & Regulatory","title":"Banking, finance, tax and regulatory law in Belize","text":"A financing or regulatory decision can shape how a business operates for years. A borrower needs to understand what it is promising beyond repayment. A lender needs to know who can bind the borrower and what supports the loan. A company considering a new activity needs to identify which legal requirements apply before committing funds or approaching customers. We review and draft financing documents and advise on Belize tax and regulatory matters. We assist with questions arising in local and cross-border transactions, including regulatory matters involving the offshore sector where relevant to the instruction."},{"kind":"service","id":"/practice-areas/banking-finance-tax-regulatory/#how-we-can-help:facility-agreements-banking-finance-tax-and-regulatory","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"how-we-can-help","page":"Banking, Finance, Tax & Regulatory","title":"Facility agreements (Banking, Finance, Tax & Regulatory)","text":"Consider conditions to draw down funds, reporting obligations, restrictions during the term, events of default and the process for repayment or amendment. These terms can affect day-to-day operations even when payments are current."},{"kind":"service","id":"/practice-areas/banking-finance-tax-regulatory/#how-we-can-help:guarantees-and-security-banking-finance-tax-and-regulatory","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"how-we-can-help","page":"Banking, Finance, Tax & Regulatory","title":"Guarantees and security (Banking, Finance, Tax & Regulatory)","text":"Review guarantees, mortgages and charges in the context of the transaction. The legal review can address the person or entity providing security, the asset involved, signing authority and the steps needed to record the interest where applicable."},{"kind":"service","id":"/practice-areas/banking-finance-tax-regulatory/#how-we-can-help:tax-advice-and-representation-banking-finance-tax-and-regulatory","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"how-we-can-help","page":"Banking, Finance, Tax & Regulatory","title":"Tax advice and representation (Banking, Finance, Tax & Regulatory)","text":"Discuss the Belize legal issue behind an assessment, transaction or compliance question. Tax matters may require coordination with your accountant or another specialist, especially where several jurisdictions or reporting systems are involved."},{"kind":"service","id":"/practice-areas/banking-finance-tax-regulatory/#how-we-can-help:regulatory-questions-banking-finance-tax-and-regulatory","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"how-we-can-help","page":"Banking, Finance, Tax & Regulatory","title":"Regulatory questions (Banking, Finance, Tax & Regulatory)","text":"Identify the activity being proposed, who will carry it out, where customers are located and which regulator may have responsibility. Where a licence or registration is relevant, discuss the scope of the permission and what needs to be checked before implementation."},{"kind":"section","id":"/practice-areas/banking-finance-tax-regulatory/#which-authority-is-relevant:which-authority-is-relevant","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"which-authority-is-relevant","page":"Banking, Finance, Tax & Regulatory","title":"Which authority is relevant?","text":"The Central Bank of Belize publishes exchange-control guidance. The Financial Services Commission regulates financial service providers within its remit and offers tools to check provider status. The Belize Tax Service administers Belize’s tax laws. The authority involved depends on the issue, and a single transaction may bring more than one into the discussion. If a transaction involves an overseas lender, investor, guarantor or payment, raise that early. The parties’ residence status, the currency and the nature of the transaction can change which questions need answering before closing."},{"kind":"section","id":"/practice-areas/banking-finance-tax-regulatory/#how-a-transaction-may-fit-together:how-a-transaction-may-fit-together","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"how-a-transaction-may-fit-together","page":"Banking, Finance, Tax & Regulatory","title":"How a transaction may fit together","text":"Suppose a Belize business is borrowing to acquire property. The purchase terms, facility agreement, security documents and company approvals may each involve different parties and deadlines. The order matters. A lender may want title or signing documents before releasing funds, while the seller may expect payment by a fixed date. Counsel can identify the documents and decisions that need to be coordinated. An accountant or other specialist can address questions that sit outside the legal instruction. If the matter concerns a proposed regulated business, begin by describing what will actually happen. An intermediary holding client money, for instance, raises different questions from a business providing information or introducing customers. The name given to the activity is only one part of the analysis."},{"kind":"faq","id":"/practice-areas/banking-finance-tax-regulatory/#my-lender-has-issued-a-term-sheet-is-this-a-useful-time-to-contact-the-firm:my-lender-has-issued-a-term-sheet-is-this-a-useful-time-to-contact-the-firm","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"my-lender-has-issued-a-term-sheet-is-this-a-useful-time-to-contact-the-firm","page":"Banking, Finance, Tax & Regulatory","title":"My lender has issued a term sheet. Is this a useful time to contact the firm?","text":"Yes. The proposed terms can identify the main legal questions before long-form documents arrive. In particular, raise any personal guarantee, required collateral and restrictions that may affect your business."},{"kind":"faq","id":"/practice-areas/banking-finance-tax-regulatory/#can-you-advise-on-a-tax-notice:can-you-advise-on-a-tax-notice","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"can-you-advise-on-a-tax-notice","page":"Banking, Finance, Tax & Regulatory","title":"Can you advise on a tax notice?","text":"The firm’s practice includes Belize tax advice and representation. Call the office promptly if you have a notice with a response date. Keep the original notice and ask the office how to share it securely."},{"kind":"faq","id":"/practice-areas/banking-finance-tax-regulatory/#will-the-firm-obtain-a-licence-or-provide-regulated-services:will-the-firm-obtain-a-licence-or-provide-regulated-services","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"will-the-firm-obtain-a-licence-or-provide-regulated-services","page":"Banking, Finance, Tax & Regulatory","title":"Will the firm obtain a licence or provide regulated services?","text":"The firm can discuss the legal and regulatory questions raised by the proposed activity. Where an application, licence, regulated agent or other provider is needed, confirm responsibilities and the scope of work during the consultation."},{"kind":"faq","id":"/practice-areas/banking-finance-tax-regulatory/#what-documents-may-be-useful-for-an-initial-review:what-documents-may-be-useful-for-an-initial-review","route":"/practice-areas/banking-finance-tax-regulatory/","anchor":"what-documents-may-be-useful-for-an-initial-review","page":"Banking, Finance, Tax & Regulatory","title":"What documents may be useful for an initial review?","text":"The financing summary, relevant agreements, description of any collateral, and the general residence or location of the parties can help orient the discussion. A regulator’s notice may also be relevant. Ask how to share it with the office."},{"kind":"intro","id":"/practice-areas/dispute-resolution/#:dispute-resolution-in-belize","route":"/practice-areas/dispute-resolution/","anchor":"","page":"Dispute Resolution","title":"Dispute resolution in Belize","text":"When a dispute arises, the first decision is often about timing. A reply may already be due. The parties may still be doing business together. Records may be scattered across emails, messages and contracts. An early review can help establish what needs attention now and which decisions can wait until the facts are clearer. The practice advises and represents clients in court proceedings in Belize and in arbitration and mediation. We can discuss both the legal issues and the practical consequences of choosing a particular route."},{"kind":"service","id":"/practice-areas/dispute-resolution/#how-we-can-help:review-of-the-dispute-dispute-resolution","route":"/practice-areas/dispute-resolution/","anchor":"how-we-can-help","page":"Dispute Resolution","title":"Review of the dispute (Dispute Resolution)","text":"Start with the agreement, what each party expected to happen, what actually happened and what you want to achieve. A timeline helps distinguish established events from points the parties disagree about. If the contract sets out a notice or dispute procedure, bring it to the discussion."},{"kind":"service","id":"/practice-areas/dispute-resolution/#how-we-can-help:litigation-dispute-resolution","route":"/practice-areas/dispute-resolution/","anchor":"how-we-can-help","page":"Dispute Resolution","title":"Litigation (Dispute Resolution)","text":"Where court proceedings are appropriate, counsel can discuss how the matter may be brought or defended and which documents and evidence need attention. If you have already received court papers, call the office and say when and how you received them."},{"kind":"service","id":"/practice-areas/dispute-resolution/#how-we-can-help:arbitration-dispute-resolution","route":"/practice-areas/dispute-resolution/","anchor":"how-we-can-help","page":"Dispute Resolution","title":"Arbitration (Dispute Resolution)","text":"If an agreement provides for arbitration, review the clause early. The forum, applicable rules and scope of the clause can affect how the parties should proceed. Counsel can advise on representation in an arbitration involving Belize."},{"kind":"service","id":"/practice-areas/dispute-resolution/#how-we-can-help:mediation-and-settlement-dispute-resolution","route":"/practice-areas/dispute-resolution/","anchor":"how-we-can-help","page":"Dispute Resolution","title":"Mediation and settlement (Dispute Resolution)","text":"Mediation gives parties a structured opportunity to explore a resolution with a neutral third party. The firm can advise or represent a party during that process. The Senior Courts of Belize publish information about court-connected mediation and their roster of mediators."},{"kind":"section","id":"/practice-areas/dispute-resolution/#what-helps-at-the-outset:what-helps-at-the-outset","route":"/practice-areas/dispute-resolution/","anchor":"what-helps-at-the-outset","page":"Dispute Resolution","title":"What helps at the outset","text":"Make a note of key dates and preserve existing contracts, messages, invoices, notices and documents in their original form. Keep track of where they came from. If a conversation took place verbally, note when it happened and who was present. Think about what a workable result would look like. A business may need a payment arrangement or a way to complete a project, while another client may need certainty about an obligation or a formal determination. The time, cost and enforceability of a proposed outcome matter alongside its legal merits."},{"kind":"section","id":"/practice-areas/dispute-resolution/#what-changes-with-the-type-of-dispute:what-changes-with-the-type-of-dispute","route":"/practice-areas/dispute-resolution/","anchor":"what-changes-with-the-type-of-dispute","page":"Dispute Resolution","title":"What changes with the type of dispute?","text":"In a contract dispute, a signed agreement and any later changes can help explain the parties’ obligations. In a shareholder dispute, the company’s records and the rules for taking decisions may be equally important. In a property dispute, the title record may need to be read alongside plans, documents about access and the history of the parties’ use. Tell the office what you have and which facts are disputed. Where a commercial relationship is still active, consider what needs to continue while the dispute is being addressed. Outstanding work, customer commitments and payment arrangements can each matter to the choices counsel discusses with you."},{"kind":"faq","id":"/practice-areas/dispute-resolution/#should-i-reply-to-a-demand-letter-before-contacting-the-firm:should-i-reply-to-a-demand-letter-before-contacting-the-firm","route":"/practice-areas/dispute-resolution/","anchor":"should-i-reply-to-a-demand-letter-before-contacting-the-firm","page":"Dispute Resolution","title":"Should I reply to a demand letter before contacting the firm?","text":"Contact counsel promptly if a demand or notice gives a response date. Share the date with the office, and ask how to provide the letter. Your attorney can review whether a reply is needed and what it should address."},{"kind":"faq","id":"/practice-areas/dispute-resolution/#is-mediation-the-same-as-arbitration:is-mediation-the-same-as-arbitration","route":"/practice-areas/dispute-resolution/","anchor":"is-mediation-the-same-as-arbitration","page":"Dispute Resolution","title":"Is mediation the same as arbitration?","text":"Mediation facilitates discussion aimed at an agreed resolution. Arbitration generally involves a decision by an arbitrator under the applicable agreement and rules. The right question is which route is available and appropriate in the circumstances."},{"kind":"faq","id":"/practice-areas/dispute-resolution/#can-i-discuss-a-settlement-while-proceedings-are-under-way:can-i-discuss-a-settlement-while-proceedings-are-under-way","route":"/practice-areas/dispute-resolution/","anchor":"can-i-discuss-a-settlement-while-proceedings-are-under-way","page":"Dispute Resolution","title":"Can I discuss a settlement while proceedings are under way?","text":"Ask counsel about settlement options and how they fit with any existing procedural obligations. Negotiations and scheduled court steps may need to be managed at the same time."},{"kind":"faq","id":"/practice-areas/dispute-resolution/#can-the-office-confirm-my-deadline-by-email-or-chat:can-the-office-confirm-my-deadline-by-email-or-chat","route":"/practice-areas/dispute-resolution/","anchor":"can-the-office-confirm-my-deadline-by-email-or-chat","page":"Dispute Resolution","title":"Can the office confirm my deadline by email or chat?","text":"A deadline can depend on the document, service, applicable rules and any court order. Call the office promptly to discuss obtaining legal review, and keep track of the dates shown on the papers you received."},{"kind":"intro","id":"/practice-areas/intellectual-property/#:intellectual-property-law-in-belize","route":"/practice-areas/intellectual-property/","anchor":"","page":"Intellectual Property","title":"Intellectual property law in Belize","text":"A name, design, invention or creative work can hold much of a business’s value. The legal questions are often practical. Who owns the logo a contractor designed? Does a company registration protect a brand? What should an inventor do before showing a prototype to someone else? The firm assists with registration of trademarks and patents and advises on copyright protection in Belize. Start with the asset, how you intend to use it and where you need protection."},{"kind":"service","id":"/practice-areas/intellectual-property/#how-we-can-help:trademarks-intellectual-property","route":"/practice-areas/intellectual-property/","anchor":"how-we-can-help","page":"Intellectual Property","title":"Trademarks (Intellectual Property)","text":"Discuss what should be protected, who should own it and the goods or services the mark will cover. A word mark and a logo can present different filing questions. Early discussion is particularly useful before committing to packaging, signage, a domain or a public launch."},{"kind":"service","id":"/practice-areas/intellectual-property/#how-we-can-help:patents-intellectual-property","route":"/practice-areas/intellectual-property/","anchor":"how-we-can-help","page":"Intellectual Property","title":"Patents (Intellectual Property)","text":"Discuss whether a patent filing deserves consideration and where you may want protection. If an invention is still private, tell the office about planned presentations or disclosures in general terms and ask for a suitable channel before sharing technical details."},{"kind":"service","id":"/practice-areas/intellectual-property/#how-we-can-help:copyright-intellectual-property","route":"/practice-areas/intellectual-property/","anchor":"how-we-can-help","page":"Intellectual Property","title":"Copyright (Intellectual Property)","text":"Discuss ownership and use of original creative work, including questions arising from commissioning, employment or licensing. The Belize Intellectual Property Office describes copyright protection as arising automatically on creation and offers a deposit facility. An attorney can review the work, the agreement and the issue you need to resolve."},{"kind":"service","id":"/practice-areas/intellectual-property/#how-we-can-help:protection-beyond-belize-intellectual-property","route":"/practice-areas/intellectual-property/","anchor":"how-we-can-help","page":"Intellectual Property","title":"Protection beyond Belize (Intellectual Property)","text":"If your business already sells elsewhere or plans to expand, make a list of the markets that matter. Registration and enforcement questions can differ by country. Discuss which work the firm can handle in Belize and where advisers elsewhere may be needed."},{"kind":"section","id":"/practice-areas/intellectual-property/#where-belipo-fits:where-belipo-fits","route":"/practice-areas/intellectual-property/","anchor":"where-belipo-fits","page":"Intellectual Property","title":"Where BELIPO fits","text":"The Belize Intellectual Property Office is the national intellectual property registry. It publishes information about trademark and patent applications. The legal work begins with identifying the asset and the proposed owner. A filing may follow if it fits the client’s objectives. The registry determines the outcome of applications it examines."},{"kind":"section","id":"/practice-areas/intellectual-property/#protecting-ip-as-part-of-a-wider-transaction:protecting-ip-as-part-of-a-wider-transaction","route":"/practice-areas/intellectual-property/","anchor":"protecting-ip-as-part-of-a-wider-transaction","page":"Intellectual Property","title":"Protecting IP as part of a wider transaction","text":"A business may acquire a brand with a purchase, license a logo for use by a distributor or commission new material for a launch. In each case, identify the asset precisely and discuss who can use it, where, for how long and under what terms. If the party providing the asset commissioned it from someone else, ask counsel to review the ownership records and agreements that come with it."},{"kind":"faq","id":"/practice-areas/intellectual-property/#is-registering-a-company-or-business-name-the-same-as-registering-a-trademark:is-registering-a-company-or-business-name-the-same-as-registering-a-trademark","route":"/practice-areas/intellectual-property/","anchor":"is-registering-a-company-or-business-name-the-same-as-registering-a-trademark","page":"Intellectual Property","title":"Is registering a company or business name the same as registering a trademark?","text":"They serve different purposes. Company or business-name registration deals with the business record. Trademark registration addresses protection of a mark in connection with goods or services. Discuss both if the brand is important to your venture."},{"kind":"faq","id":"/practice-areas/intellectual-property/#does-a-foreign-trademark-cover-belize:does-a-foreign-trademark-cover-belize","route":"/practice-areas/intellectual-property/","anchor":"does-a-foreign-trademark-cover-belize","page":"Intellectual Property","title":"Does a foreign trademark cover Belize?","text":"Protection depends on the registrations or designations in place. Share the jurisdiction and general nature of the existing protection with the office and ask whether a Belize filing or review may be needed."},{"kind":"faq","id":"/practice-areas/intellectual-property/#can-i-send-my-invention-details-through-the-website:can-i-send-my-invention-details-through-the-website","route":"/practice-areas/intellectual-property/","anchor":"can-i-send-my-invention-details-through-the-website","page":"Intellectual Property","title":"Can I send my invention details through the website?","text":"Call the office first. Describe the kind of assistance you are seeking and mention any planned disclosure date. The office can explain how to provide sensitive material if a review is arranged."},{"kind":"faq","id":"/practice-areas/intellectual-property/#what-if-another-business-is-already-using-a-similar-name:what-if-another-business-is-already-using-a-similar-name","route":"/practice-areas/intellectual-property/","anchor":"what-if-another-business-is-already-using-a-similar-name","page":"Intellectual Property","title":"What if another business is already using a similar name?","text":"Preserve what you have seen and note when you found it. The firm can discuss whether the issue raises a registration, ownership or dispute question. Avoid drawing conclusions about infringement from a name alone."},{"kind":"intro","id":"/practice-areas/family-law/#:family-law-in-belize","route":"/practice-areas/family-law/","anchor":"","page":"Family Law","title":"Family law in Belize","text":"A family matter may involve decisions about children, housing, finances and existing responsibilities at the same time. It can be difficult to tell which decisions are urgent or which arrangements need formal legal attention. An initial conversation gives you space to identify the issue and understand what the next step may involve. We advise and represent clients in divorce, adoptions and other family matters involving Belize. Begin by telling the office the type of matter and whether there are existing proceedings, orders or important dates. You can discuss personal details with the attorney once the office has explained how to proceed."},{"kind":"service","id":"/practice-areas/family-law/#how-we-can-help:divorce-and-separation-family-law","route":"/practice-areas/family-law/","anchor":"how-we-can-help","page":"Family Law","title":"Divorce and separation (Family Law)","text":"Discuss the status of the relationship, any existing arrangements and the decisions that remain unresolved. A divorce may raise separate issues about property, financial arrangements or children. The attorney can explain which questions need to be addressed in your circumstances."},{"kind":"service","id":"/practice-areas/family-law/#how-we-can-help:adoption-family-law","route":"/practice-areas/family-law/","anchor":"how-we-can-help","page":"Family Law","title":"Adoption (Family Law)","text":"Discuss the circumstances and the Belize legal steps that may be relevant, including the role of the court or authorities where applicable. If a child or prospective parent has a connection to another country, raise that at the outset so the cross-border questions can be identified early."},{"kind":"service","id":"/practice-areas/family-law/#how-we-can-help:family-arrangements-and-existing-orders-family-law","route":"/practice-areas/family-law/","anchor":"how-we-can-help","page":"Family Law","title":"Family arrangements and existing orders (Family Law)","text":"If your concern involves arrangements for a child, maintenance or another issue affecting the family, tell the office whether an agreement, application or order already exists. The Attorney General’s Ministry publishes an overview of the matters the Belize Family Court hears. An attorney can assess the appropriate process and forum for your situation."},{"kind":"section","id":"/practice-areas/family-law/#making-the-first-conversation-easier:making-the-first-conversation-easier","route":"/practice-areas/family-law/","anchor":"making-the-first-conversation-easier","page":"Family Law","title":"Making the first conversation easier","text":"Make a private list of any hearing dates, orders and agreements, and note what you need help deciding. A marriage certificate, court papers or other records may be relevant later. Ask the office how to share them before sending anything that identifies children or contains sensitive information. If someone else can access your phone or email and you are concerned about privacy, use a contact method that is safe for you. In an immediate emergency in Belize, contact emergency services on 911."},{"kind":"faq","id":"/practice-areas/family-law/#can-we-speak-before-i-decide-whether-to-start-a-court-process:can-we-speak-before-i-decide-whether-to-start-a-court-process","route":"/practice-areas/family-law/","anchor":"can-we-speak-before-i-decide-whether-to-start-a-court-process","page":"Family Law","title":"Can we speak before I decide whether to start a court process?","text":"Yes. The purpose of an initial discussion is to understand your concerns and identify the questions that need legal review. You can raise your priorities, existing arrangements and concerns about timing with counsel."},{"kind":"faq","id":"/practice-areas/family-law/#what-if-we-have-already-reached-an-agreement:what-if-we-have-already-reached-an-agreement","route":"/practice-areas/family-law/","anchor":"what-if-we-have-already-reached-an-agreement","page":"Family Law","title":"What if we have already reached an agreement?","text":"Mention whether the arrangement was discussed, written down, signed or made into a court order. Those distinctions can matter. Counsel can review the document and explain what additional steps, if any, merit consideration."},{"kind":"faq","id":"/practice-areas/family-law/#what-if-a-spouse-parent-or-child-lives-outside-belize:what-if-a-spouse-parent-or-child-lives-outside-belize","route":"/practice-areas/family-law/","anchor":"what-if-a-spouse-parent-or-child-lives-outside-belize","page":"Family Law","title":"What if a spouse, parent or child lives outside Belize?","text":"Tell the office the countries involved and whether there are any existing orders or proceedings. Residence, service and recognition of orders can raise questions in more than one jurisdiction."},{"kind":"faq","id":"/practice-areas/family-law/#how-can-i-enquire-without-sharing-sensitive-information-online:how-can-i-enquire-without-sharing-sensitive-information-online","route":"/practice-areas/family-law/","anchor":"how-can-i-enquire-without-sharing-sensitive-information-online","page":"Family Law","title":"How can I enquire without sharing sensitive information online?","text":"Call the office or send a brief enquiry saying it concerns a family matter. Leave out names of children, identification numbers and details of the situation until the office confirms an appropriate way to speak."},{"kind":"intro","id":"/practice-areas/qualified-retired-persons/#:qualified-retired-persons-programme-in-belize","route":"/practice-areas/qualified-retired-persons/","anchor":"","page":"Qualified Retired Persons Programme","title":"Qualified Retired Persons Programme in Belize","text":"A move to Belize is a series of decisions about where to live, how to support yourself and which commitments to make before you arrive. If you are considering the Qualified Retired Persons Programme, an early discussion can help you plan those decisions around the application and any conditions that may apply. The Belize Tourism Board administers the programme and refers to it as the Qualified Retirement Program, or QRP. The firm advises prospective applicants on the legal questions raised by the programme and on related matters such as property purchases. Janine Ebanks-Alpuche previously administered the QRP at the Belize Tourism Board and now manages the firm’s practice."},{"kind":"service","id":"/practice-areas/qualified-retired-persons/#how-we-can-help:understand-the-programme-in-the-context-of-your-plans-qualified-retired-persons-programme","route":"/practice-areas/qualified-retired-persons/","anchor":"how-we-can-help","page":"Qualified Retired Persons Programme","title":"Understand the programme in the context of your plans (Qualified Retired Persons Programme)","text":"Discuss who is planning to move, where they currently live, what income they expect to rely on and whether family members may need to be included. The Belize Tourism Board’s QRP guidance is the starting point for current criteria and documentation."},{"kind":"service","id":"/practice-areas/qualified-retired-persons/#how-we-can-help:plan-the-application-sequence-qualified-retired-persons-programme","route":"/practice-areas/qualified-retired-persons/","anchor":"how-we-can-help","page":"Qualified Retired Persons Programme","title":"Plan the application sequence (Qualified Retired Persons Programme)","text":"Different records may need to be obtained from different authorities or institutions, and some have timing or certification requirements. Build time into your plans for records about identity, family relationships, background and income where relevant. Ask the office to confirm a suitable channel for sharing documents."},{"kind":"service","id":"/practice-areas/qualified-retired-persons/#how-we-can-help:connect-relocation-and-real-estate-decisions-qualified-retired-persons-programme","route":"/practice-areas/qualified-retired-persons/","anchor":"how-we-can-help","page":"Qualified Retired Persons Programme","title":"Connect relocation and real estate decisions (Qualified Retired Persons Programme)","text":"Decide whether you plan to rent first or buy, and discuss how your property plans relate to the move. A purchase deserves its own title and transaction review. If you are negotiating from overseas, raise your proposed signing arrangements and the movement of funds early."},{"kind":"service","id":"/practice-areas/qualified-retired-persons/#how-we-can-help:review-plans-for-personal-goods-or-business-activity-qualified-retired-persons-programme","route":"/practice-areas/qualified-retired-persons/","anchor":"how-we-can-help","page":"Qualified Retired Persons Programme","title":"Review plans for personal goods or business activity (Qualified Retired Persons Programme)","text":"The programme publishes conditions relating to possible benefits and ongoing obligations. If you are considering shipping goods, importing a vehicle, working or carrying on business, raise those plans before making commitments. Permissions and treatment can depend on the activity and the relevant rules."},{"kind":"section","id":"/practice-areas/qualified-retired-persons/#what-the-belize-tourism-board-assesses:what-the-belize-tourism-board-assesses","route":"/practice-areas/qualified-retired-persons/","anchor":"what-the-belize-tourism-board-assesses","page":"Qualified Retired Persons Programme","title":"What the Belize Tourism Board assesses","text":"The BTB’s published criteria cover age, eligible applicants and dependants, evidence of retirement income from outside Belize, a deposit undertaking, security clearance and time spent in Belize. Its guidance also sets out renewal steps and conditions for specific benefits. These are separate questions to review against your plans. When planning a move, budget for the application, document preparation and renewals as well as travel and housing. Confirm current requirements and charges with the BTB before relying on them."},{"kind":"section","id":"/practice-areas/qualified-retired-persons/#questions-to-consider-before-committing-to-a-move:questions-to-consider-before-committing-to-a-move","route":"/practice-areas/qualified-retired-persons/","anchor":"questions-to-consider-before-committing-to-a-move","page":"Qualified Retired Persons Programme","title":"Questions to consider before committing to a move","text":"Identify your preferred timing, who will move with you, whether you plan to work or invest, and what financial or travel arrangements you will need. If you are looking at property, decide which commitments can wait until the legal and programme questions are clearer. Keep a list of what you need to confirm with the firm, the Belize Tourism Board, and advisers in your home country where appropriate."},{"kind":"faq","id":"/practice-areas/qualified-retired-persons/#will-i-qualify-for-the-qrp:will-i-qualify-for-the-qrp","route":"/practice-areas/qualified-retired-persons/","anchor":"will-i-qualify-for-the-qrp","page":"Qualified Retired Persons Programme","title":"Will I qualify for the QRP?","text":"The Belize Tourism Board assesses applications under its current requirements. The firm can discuss the criteria in light of your plans and identify questions that need to be confirmed. Call the office to discuss your circumstances."},{"kind":"faq","id":"/practice-areas/qualified-retired-persons/#does-the-qrp-settle-every-residency-employment-or-tax-question:does-the-qrp-settle-every-residency-employment-or-tax-question","route":"/practice-areas/qualified-retired-persons/","anchor":"does-the-qrp-settle-every-residency-employment-or-tax-question","page":"Qualified Retired Persons Programme","title":"Does the QRP settle every residency, employment or tax question?","text":"The programme has its own status and conditions. If you have separate questions about permanent residency, permission to work or tax residence, raise them directly and ask what additional advice or referrals may be needed."},{"kind":"faq","id":"/practice-areas/qualified-retired-persons/#can-i-include-my-family:can-i-include-my-family","route":"/practice-areas/qualified-retired-persons/","anchor":"can-i-include-my-family","page":"Qualified Retired Persons Programme","title":"Can I include my family?","text":"The programme provides for eligible dependants under its published conditions. Discuss who plans to move and check the current requirements before relying on a particular application plan."},{"kind":"faq","id":"/practice-areas/qualified-retired-persons/#should-i-buy-property-or-ship-belongings-before-applying:should-i-buy-property-or-ship-belongings-before-applying","route":"/practice-areas/qualified-retired-persons/","anchor":"should-i-buy-property-or-ship-belongings-before-applying","page":"Qualified Retired Persons Programme","title":"Should I buy property or ship belongings before applying?","text":"Discuss the application timeline and any separate purchase or import conditions before committing funds. The order of those decisions can affect cost and flexibility if plans change."},{"kind":"intro","id":"/working-with-us/#:what-to-expect-when-you-contact-us","route":"/working-with-us/","anchor":"","page":"What to Expect","title":"What to expect when you contact us","text":"You can contact the office even if you are unsure what kind of legal help you need. Start with the general subject, what you are trying to achieve and whether there is an upcoming date the office should know about. Janine, our practice manager, is often the first person you will speak with."},{"kind":"section","id":"/working-with-us/#1-make-a-brief-enquiry:1-make-a-brief-enquiry","route":"/working-with-us/","anchor":"1-make-a-brief-enquiry","page":"What to Expect","title":"1. Make a brief enquiry","text":"Call or email the office with your name, a reliable way to reach you and a short description of the type of matter. “Buying property in Belize,” “shareholder agreement” or “received court papers” is enough to start. Leave out sensitive details and attachments. If you received a notice or have a hearing or closing approaching, call and mention the date."},{"kind":"section","id":"/working-with-us/#2-ask-how-to-arrange-a-consultation:2-ask-how-to-arrange-a-consultation","route":"/working-with-us/","anchor":"2-ask-how-to-arrange-a-consultation","page":"What to Expect","title":"2. Ask how to arrange a consultation","text":"The office can discuss availability, any initial information the firm needs and whether a consultation is the right next step. The firm may need to check for conflicts before discussing substantive details. If you are outside Belize, tell the office your time zone and ask what meeting arrangements are available."},{"kind":"section","id":"/working-with-us/#3-prepare-for-the-discussion:3-prepare-for-the-discussion","route":"/working-with-us/","anchor":"3-prepare-for-the-discussion","page":"What to Expect","title":"3. Prepare for the discussion","text":"Write down your main question, the outcome you want and the important dates. Identify the documents you already have. For a property purchase, that may be the title reference and proposed terms. For a business matter, it may be a term sheet or a draft agreement. For a dispute, it may be the notice you received or the contract. Keep these for the meeting or ask how to provide them."},{"kind":"section","id":"/working-with-us/#4-confirm-what-the-work-will-involve:4-confirm-what-the-work-will-involve","route":"/working-with-us/","anchor":"4-confirm-what-the-work-will-involve","page":"What to Expect","title":"4. Confirm what the work will involve","text":"If the firm can assist, clarify the work to be done, responsibilities, fee arrangements and any expected third-party costs. Ask what information the attorney will need from you and whether a decision or document is needed before a step can be taken. The firm will confirm whether it has accepted the matter."},{"kind":"faq","id":"/working-with-us/#is-there-a-fee-for-the-first-meeting:is-there-a-fee-for-the-first-meeting","route":"/working-with-us/","anchor":"is-there-a-fee-for-the-first-meeting","page":"What to Expect","title":"Is there a fee for the first meeting?","text":"Ask the office about current consultation fees and arrangements before booking. Legal work and third-party charges can vary with the matter and scope."},{"kind":"faq","id":"/working-with-us/#does-contacting-the-office-mean-it-has-agreed-to-represent-me:does-contacting-the-office-mean-it-has-agreed-to-represent-me","route":"/working-with-us/","anchor":"does-contacting-the-office-mean-it-has-agreed-to-represent-me","page":"What to Expect","title":"Does contacting the office mean it has agreed to represent me?","text":"An enquiry starts a conversation. Representation requires the firm to confirm that it has accepted the matter and agreed the terms of engagement."},{"kind":"faq","id":"/working-with-us/#can-i-send-my-documents-before-a-consultation:can-i-send-my-documents-before-a-consultation","route":"/working-with-us/","anchor":"can-i-send-my-documents-before-a-consultation","page":"What to Expect","title":"Can I send my documents before a consultation?","text":"Ask the office which documents are needed and how to provide them. Keep passports, financial records, court papers and other sensitive material out of general enquiries and the website assistant."},{"kind":"intro","id":"/contact/#:contact-the-office","route":"/contact/","anchor":"","page":"Contact","title":"Contact the office","text":"To enquire about a new matter, call or send a short email with the type of assistance you are seeking and a way to reach you. Janine Ebanks-Alpuche, our practice manager, is often the first person you will speak with."},{"kind":"section","id":"/contact/#belize-city-office:belize-city-office","route":"/contact/","anchor":"belize-city-office","page":"Contact","title":"Belize City office","text":"The Northern Shops, Suite 19 1½ Miles Philip Goldson Highway Belize City, Belize Telephone +501 223-1194 or +501 223-1195 Email contact@alpuchelaw.com Office hours Monday to Friday, 8:00 a.m. to 5:00 p.m. Belize time."},{"kind":"section","id":"/contact/#request-a-consultation:request-a-consultation","route":"/contact/","anchor":"request-a-consultation","page":"Contact","title":"Request a consultation","text":"Tell us the general subject of your enquiry. If you are contacting us from outside Belize, include your time zone and preferred way to be reached. The office can tell you how to arrange an initial consultation."},{"kind":"section","id":"/contact/#if-a-date-is-approaching:if-a-date-is-approaching","route":"/contact/","anchor":"if-a-date-is-approaching","page":"Contact","title":"If a date is approaching","text":"If you have a court date, response deadline or closing approaching, call the office and mention the date. Contacting us through the website does not confirm that the firm has accepted the matter."},{"kind":"section","id":"/contact/#before-you-send-documents:before-you-send-documents","route":"/contact/","anchor":"before-you-send-documents","page":"Contact","title":"Before you send documents","text":"Leave out identification numbers, bank information, children’s details and confidential documents from your initial message. Ask the office how to share material if it is needed for review."},{"kind":"intro","id":"/insights/buying-property-in-belize/#:buying-property-in-belize","route":"/insights/buying-property-in-belize/","anchor":"","page":"Buying property in Belize","title":"Buying property in Belize","text":"A listing can help you decide whether a property is worth visiting. Before you decide whether it is worth buying, make sure the property you have seen is the same one described in the title documents, the agreement and any survey. Those documents answer different questions about the same transaction."},{"kind":"section","id":"/insights/buying-property-in-belize/#start-with-the-property-and-the-seller:start-with-the-property-and-the-seller","route":"/insights/buying-property-in-belize/","anchor":"start-with-the-property-and-the-seller","page":"Buying property in Belize","title":"Start with the property and the seller","text":"Ask for the parcel or title reference and the seller’s title documents. Tell your attorney if the person negotiating is someone other than the recorded owner, or if the seller is acting through a company or representative. The first review can identify what needs to be checked about ownership, authority and any recorded interests. The Land Registry and Land Titles Unit describes its registry functions online. If the property’s practical use depends on a road, a boundary, water access or development approval, mention that before the agreement is settled. A legal title review may need to be supplemented by advice from a surveyor, inspector, planner or other professional."},{"kind":"section","id":"/insights/buying-property-in-belize/#know-what-the-deposit-commits-you-to:know-what-the-deposit-commits-you-to","route":"/insights/buying-property-in-belize/","anchor":"know-what-the-deposit-commits-you-to","page":"Buying property in Belize","title":"Know what the deposit commits you to","text":"Find out who will hold the deposit, when it is payable and when it is refundable. If your plans depend on financing, satisfactory title checks or another event, ask counsel how the contract addresses that condition. Review what happens if either party needs more time or a condition cannot be met. These questions are easier to address while the terms are still open."},{"kind":"section","id":"/insights/buying-property-in-belize/#work-out-the-closing-sequence:work-out-the-closing-sequence","route":"/insights/buying-property-in-belize/","anchor":"work-out-the-closing-sequence","page":"Buying property in Belize","title":"Work out the closing sequence","text":"Ask what has to happen before the balance is paid and who is responsible for each step. Allow for legal costs, any applicable duties or charges, registry fees and other professional costs. Ask what you will receive at closing and what will confirm that the transfer has been recorded. For transactions between a resident and a non-resident, the Central Bank of Belize publishes prior-notice guidance. If you will sign abroad or send funds from another country, discuss the arrangements before setting the closing date."},{"kind":"section","id":"/insights/buying-property-in-belize/#have-these-points-handy-when-you-call:have-these-points-handy-when-you-call","route":"/insights/buying-property-in-belize/","anchor":"have-these-points-handy-when-you-call","page":"Buying property in Belize","title":"Have these points handy when you call","text":"A parcel reference or property description.. The proposed buyer and seller and whether either is acting through a company.. The proposed price, deposit, conditions and closing date.. Anything you have signed or agreed to already.. Any question about access, boundaries, financing or overseas signing. For general information only. The records, checks and transfer steps depend on the property and transaction."},{"kind":"intro","id":"/insights/starting-a-business-in-belize/#:starting-a-business-in-belize","route":"/insights/starting-a-business-in-belize/","anchor":"","page":"Starting a business in Belize","title":"Starting a business in Belize","text":"Before choosing a name or submitting a registration, agree on what the business will do and who will be responsible for it. That conversation can reveal whether the immediate task is formation, a written agreement between the owners, or a review of permissions and other requirements for the activity."},{"kind":"section","id":"/insights/starting-a-business-in-belize/#put-the-ownership-arrangement-on-paper:put-the-ownership-arrangement-on-paper","route":"/insights/starting-a-business-in-belize/","anchor":"put-the-ownership-arrangement-on-paper","page":"Starting a business in Belize","title":"Put the ownership arrangement on paper","text":"List the owners, what each person will contribute and who will run day-to-day operations. Decide who should be able to sign contracts or incur debt and which decisions should require the other owners’ approval. If someone intends to contribute intellectual property, property or equipment instead of cash, discuss how ownership and use will be documented. It is also worth asking what happens if an owner leaves, stops contributing or wants to sell. Agreeing a process while the relationship is working can make it easier to respond when circumstances change."},{"kind":"section","id":"/insights/starting-a-business-in-belize/#understand-what-the-registration-does:understand-what-the-registration-does","route":"/insights/starting-a-business-in-belize/","anchor":"understand-what-the-registration-does","page":"Starting a business in Belize","title":"Understand what the registration does","text":"The Belize Companies and Corporate Affairs Registry handles registration of business names, companies and limited liability partnerships through its online system. Registration of a business name and incorporation of a company are distinct steps. Discuss the structure in the context of your owners, intended contracts and the risks of the business. If a foreign participant is involved, the Registry’s guidance calls for a licensed registered agent. Check which service is needed, who will provide it and what records the owners must have ready."},{"kind":"section","id":"/insights/starting-a-business-in-belize/#look-beyond-formation:look-beyond-formation","route":"/insights/starting-a-business-in-belize/","anchor":"look-beyond-formation","page":"Starting a business in Belize","title":"Look beyond formation","text":"Think about how the business will accept payments, hire or contract for work, use a brand and occupy any premises. Tax registration, financing, exchange-control or sector-specific permissions may need separate attention. Identify the activity and the people involved before deciding which questions to raise with an attorney, accountant, bank or regulator. If you are acquiring a business or beginning with existing customers and assets, ask who owns the brand, contracts and equipment and what needs to be transferred separately. A new registration alone does not resolve those ownership questions."},{"kind":"section","id":"/insights/starting-a-business-in-belize/#prepare-for-a-first-consultation:prepare-for-a-first-consultation","route":"/insights/starting-a-business-in-belize/","anchor":"prepare-for-a-first-consultation","page":"Starting a business in Belize","title":"Prepare for a first consultation","text":"Bring a short description of the venture, the proposed owners and where they are based, any draft terms and the decision you need to make first. If you are already trading or signing agreements, say so. The next step will depend on what has already been done and what needs attention before further commitments. For general information only. Seek advice about the structure, registration and any applicable obligations for your business."},{"kind":"intro","id":"/insights/planning-retirement-in-belize/#:planning-retirement-in-belize","route":"/insights/planning-retirement-in-belize/","anchor":"","page":"Planning retirement in Belize","title":"Planning retirement in Belize","text":"People often begin with a preferred town or a date to move. Use those as planning goals and work backwards. Ask which parts of the plan depend on an application, which involve separate legal work and which commitments you can keep flexible until the position is clearer."},{"kind":"section","id":"/insights/planning-retirement-in-belize/#plan-the-status-and-the-move-separately:plan-the-status-and-the-move-separately","route":"/insights/planning-retirement-in-belize/","anchor":"plan-the-status-and-the-move-separately","page":"Planning retirement in Belize","title":"Plan the status and the move separately","text":"The Belize Tourism Board publishes current guidance on the Qualified Retirement Program, commonly called the QRP. Its criteria, documentation and conditions apply to the programme. If you plan to work, operate a business, include family members or rely on a particular tax outcome, raise those plans with counsel before you make commitments. Build in time for records that must come from elsewhere. Identity, family and income documents can take time to assemble and may need certification. Before ordering documents or paying for translations, check the current guidance and ask which records are relevant to your application."},{"kind":"section","id":"/insights/planning-retirement-in-belize/#decide-whether-to-rent-or-buy-first:decide-whether-to-rent-or-buy-first","route":"/insights/planning-retirement-in-belize/","anchor":"decide-whether-to-rent-or-buy-first","page":"Planning retirement in Belize","title":"Decide whether to rent or buy first","text":"Renting initially can give you time to understand a community before buying. If you already have a property in mind, discuss the title, proposed agreement and how the purchase fits with your move. A transaction with overseas parties or funds can raise signing, payment and exchange-control questions that are separate from the programme. Ask what the purchase agreement requires if plans change, including what happens to any deposit and when the parties must close. The same planning principle applies to a long lease or a shipment of personal goods."},{"kind":"section","id":"/insights/planning-retirement-in-belize/#check-conditions-before-booking-a-shipment:check-conditions-before-booking-a-shipment","route":"/insights/planning-retirement-in-belize/","anchor":"check-conditions-before-booking-a-shipment","page":"Planning retirement in Belize","title":"Check conditions before booking a shipment","text":"If you are considering importing household goods or a vehicle, check the current rules and timing before signing a shipping agreement or buying something specifically for import. Ask what approvals or documents you may need and whether there are conditions tied to a programme benefit. Plan for the possibility that shipping and application timelines will differ."},{"kind":"section","id":"/insights/planning-retirement-in-belize/#decide-what-to-raise-with-the-firm:decide-what-to-raise-with-the-firm","route":"/insights/planning-retirement-in-belize/","anchor":"decide-what-to-raise-with-the-firm","page":"Planning retirement in Belize","title":"Decide what to raise with the firm","text":"Who expects to move and where they currently live.. Whether you are considering QRP status or comparing other options.. Whether you plan to rent, buy, work or run a business.. Which travel, housing or shipping commitments are already in place.. The dates that matter most and where you still have flexibility. For general planning information only. Current programme requirements and any decision on an application rest with the relevant authorities."},{"kind":"intro","id":"/website-notice/#:website-and-ai-assistant-notice","route":"/website-notice/","anchor":"","page":"Website notice","title":"Website and AI assistant notice","text":"The website provides general information about the practice and about legal topics involving Belize. Seek advice from an attorney about your own matter. Rules, procedures and agency requirements may change."},{"kind":"section","id":"/website-notice/#contacting-the-firm:contacting-the-firm","route":"/website-notice/","anchor":"contacting-the-firm","page":"Website notice","title":"Contacting the firm","text":"Sending an enquiry, using the website assistant or receiving a reply about availability does not establish an attorney–client relationship. The firm must confirm that it has accepted a matter and agreed the terms of engagement. If a legal deadline or hearing is approaching, call the office promptly. Do not use the website or assistant to serve documents or notify the firm of a deadline."},{"kind":"section","id":"/website-notice/#using-the-website-assistant:using-the-website-assistant","route":"/website-notice/","anchor":"using-the-website-assistant","page":"Website notice","title":"Using the website assistant","text":"The website assistant, Alpuche AI, is automated. It can answer general questions using information published on this website, help you find a practice area or public office contact information, and pass a short enquiry to the office. It cannot review your case, calculate a deadline, accept instructions, confirm an appointment or give legal advice. If you choose to send an enquiry, Alpuche AI asks for your name, how you would like to be contacted, your email address or phone number, the type of matter, whether a date is coming up and a short, general description. It shows you a summary before anything is sent. The enquiry is sent to the office by email and, if you give an email address, you receive an automated confirmation. Please keep confidential details, identification numbers, financial records and documents out of the chat and the enquiry."},{"kind":"section","id":"/website-notice/#external-information:external-information","route":"/website-notice/","anchor":"external-information","page":"Website notice","title":"External information","text":"Links to official registries, regulators and other organisations are provided for general reference. Those organisations maintain their own information and requirements."},{"kind":"section","id":"/website-notice/#photo-credits:photo-credits","route":"/website-notice/","anchor":"photo-credits","page":"Website notice","title":"Photo credits","text":"Belize City harbour, Belize by Jasmine Halki, CC BY 2.0.. Belize City Courthouse by Haakon S. Krohn, CC BY-SA 3.0.. Macal River at San Ignacio by Kaldari, CC0 1.0.. Beach front at Placencia, Belize by Dave ten Broek, CC BY 2.0.. Baron Bliss Lighthouse in Belize City, Belize. Photo by Didier Moïse, CC BY-SA 4.0."},{"kind":"section","id":"/website-notice/#contact:contact","route":"/website-notice/","anchor":"contact","page":"Website notice","title":"Contact","text":"Call +501 223-1194 or view contact information."}],"pages":{"/":"Home","/about/":"Our Team","/practice-areas/":"Practice Areas","/practice-areas/real-estate/":"Real Estate","/practice-areas/corporate-commercial/":"Corporate & Commercial","/practice-areas/banking-finance-tax-regulatory/":"Banking, Finance, Tax & Regulatory","/practice-areas/dispute-resolution/":"Dispute Resolution","/practice-areas/intellectual-property/":"Intellectual Property","/practice-areas/family-law/":"Family Law","/practice-areas/qualified-retired-persons/":"Qualified Retired Persons Programme","/working-with-us/":"What to Expect","/contact/":"Contact","/insights/":"Belize Legal Guides","/insights/buying-property-in-belize/":"Buying property in Belize","/insights/starting-a-business-in-belize/":"Starting a business in Belize","/insights/planning-retirement-in-belize/":"Planning retirement in Belize","/website-notice/":"Website notice"},"nextLabels":{"/about/":"Meet José and Janine","/contact/":"View office contact details","/practice-areas/":"Browse practice areas","/working-with-us/":"See what to expect","/website-notice/":"Read the website notice","/insights/buying-property-in-belize/":"Read the property purchase guide","/insights/starting-a-business-in-belize/":"Read the business start-up guide","/insights/planning-retirement-in-belize/":"Read the retirement planning guide","/practice-areas/qualified-retired-persons/":"Explore the retirement programme","https://www.belizetourismboard.org/programs-events/retirement-program/":"Belize Tourism Board QRP guidance","https://www.belizepolice.bz/about-911/":"Belize Police 911 information"},"transport":{"mode":"demo","endpoint":"","whatsapp":"5016253032","firmWhatsApp":true}}; })(typeof self !== 'undefined' ? self : this);
